        heading: 'Forte e fraca',
        text: 'A gradação atinge o k, o p e o t no começo da última sílaba da palavra. Cada palavra tem uma forma forte (a do dicionário, na maioria dos casos) e uma fraca. Existem dois tipos de troca. Na troca de quantidade, a consoante dupla vira simples: kk → k, pp → p, tt → t (kukka → kukan, kauppa → kaupan, katto → katon). Na troca de qualidade, a consoante muda de som: t → d (katu → kadun), p → v (leipä → leivän), k some (ruoka → ruoan), nk → ng (kenkä → kengän), nt → nn (ranta → rannan), lt → ll (ilta → illan), rt → rr (parta → parran), mp → mm (kampa → kamman).',
