        heading: 'Quando entra a forma fraca',
        text: 'A regra de bolso: se a terminação fecha a última sílaba com consoante, a consoante do meio enfraquece. kuk-ka (sílaba aberta, forte) → ku-kan (sílaba «kan», fechada pelo -n: fraca). Por isso o genitivo (-n), o plural (-t), o -ssa, -sta, -lla, -lta, -lle e as pessoas -n, -t, -mme, -tte dos verbos pedem a fraca: kukan, kukat, kukassa, kukalla; nukun, nukut. Já as terminações que começam com vogal longa ou deixam a sílaba aberta mantêm a forte: o partitivo (kukkaa), o ilativo (kukkaan) e a terceira pessoa dos verbos (nukkuu, nukkuvat).',
