        text: 'O comparativo é -mpi, colado ao radical do genitivo (sem o -n): iso → ison → isompi; kaunis → kauniin → kauniimpi; uusi → uuden → uudempi; nopea → nopeampi. Nos adjetivos de duas sílabas terminados em -a/-ä, essa vogal vira -e: vanha → vanhempi, halpa → halvempi, köyhä → köyhempi. O superlativo é -in: iso → isoin, suuri → suurin, vanha → vanhin, halpa → halvin, kaunis → kaunein, uusi → uusin. Nele, o -a/-ä e o -e do radical caem antes do i (vanh-in, suur-in, nope-in), e as vogais o, u, ö, y ficam (iso-in, helpo-in). E há os irregulares de sempre.',
