        text: 'Quase todo finlandês domina dois registros: o yleiskieli (a língua padrão, escrita, dos jornais e dos documentos) e o puhekieli (a língua falada, que varia de região para região). A distância entre os dois é grande, e é por isso que muitos estrangeiros entendem o jornal mas se perdem numa conversa. O modelo aqui é a fala de Helsinque e do sul, a mais ouvida na mídia. No leste e no norte, muda bastante: em vez de mä e sä, diz-se mie e sie.',
