        text: 'Os provérbios guardam estruturas que vale a pena reconhecer. O par «joka…, se…» (quem…, esse…) põe o relativo antes e o pronome depois: «Joka toiselle kuoppaa kaivaa, se itse siihen lankeaa» (quem cava um buraco para o outro cai nele). O par «minkä…, sen…» faz o mesmo com o objeto. A pessoa zero, com o verbo na 3ª pessoa sem sujeito, dá o sentido universal: «Minkä nuorena oppii» (o que [a gente] aprende jovem). E o comparativo usa o partitivo no lugar de «kuin»: «iltaa viisaampi» = «viisaampi kuin ilta».',
